/* The final six trilogies resolve the same ledger; every chapter owns its evidence and route. */
const FinaleChapters=[
 {id:'lifemirror',no:'贰拾伍',title:'照命非价',subtitle:'照命河',place:'照命河 · 返照渡',color:'#a1d5db',boss:'照命女相',bossGlyph:'照',theme:'倒影照得见你的脸，却凭什么替你定一生的价？',
  mobNames:{imp:'照命苇甲卒',fox:'银波镜獒',snake:'返照帷祭师',zombie:'铜镜溺甲卫'},
  story:['金兜带出的半幅河图，在晨光里显出另一条河。孙小果踏进照命渡，看见岸上人人低头：河中倒影先替他们报出身价，活人才被允许开口。','照命女相声称镜水从不说谎。可病者的倒影总比旁人黯淡，穷人的脸总被涂去一角；所谓天生贵贱，是有人先把秤放在了水底。太玄玉髓正压着那枚秤砣。','大圣曾在河面留下一道没有倒影的脚印。他没有砸碎所有镜子，只把写着价目的那面翻了过来。小果循着两岸真正的人影换位，要让水只照人，不再替账房定价。'],
  lore:['渡口卖镜人说，照命镜从来免费。直到你想走另一条路，才知道那张价签会跟你一辈子。','河底的穷字并非天然水纹，而是同一支朱笔反复描过的痕迹。','没有倒影的脚印旁压着一根金毫：看见一个人的苦，不等于有权替他定命。'],
  tell:'照命水先留下右岸弯月，再留下左岸弯月，最后回中央扁圆镜心。弯月的内圈和扇区边线都不安全，认准青色水面连续换位。',mechanic:'返照弯月：右弧、左弧、中央镜心。',bossLine:'“镜子没有偏心，只是有些人本来就不值钱。”',phaseLine:'“价签烧了，照命的权还在我手里！”',omen:'先右岸弯月，再左岸弯月，最后回镜心！',weakness:'水只照人，不再替谁定价！',
  reveal:'河底的秤被抬上岸，所有倒影终于和人一样高。秤柄上却有毒敌山的封蜡：改不掉价目的人，会被送去医治不服。',clue:{name:'毒敌山诊籍',text:'照命负责给人定价，毒敌山负责让异议闭口。小果带着太玄玉髓进入回声穴，去听那些被诊成病的证词。'},reward:'镜中再无贵贱。照见自己，从来不该先付赎身钱。',regions:['低头渡口','朱笔镜岸','无影长堤','返照镜坛'],siteNames:['免费照命告示','水底朱笔痕','无影金毫刻','镜底旧匣','返照药亭','返照镜坛']},
 {id:'scorpionecho',no:'贰拾陆',title:'毒敌还言',subtitle:'毒敌回声穴',place:'毒敌山 · 回声穴',color:'#c8a4e6',boss:'钩魂蝎后',bossGlyph:'言',theme:'谁把说真话的人，诊成了需要治好的病人？',
  mobNames:{imp:'毒籍钩枪卒',fox:'紫甲蝎獒',snake:'回声药铃师',zombie:'黑螯重甲卫'},
  story:['诊籍记着许多相同的病名：不肯认命、反复申诉、仍问原由。回声穴的药池边，病人喝下止痛汤，先忘了疼，接着忘了是谁让他们疼。','钩魂蝎后把毒分成三等：给富人的是安睡，给穷人的是顺从，给证人的是永不醒来的平静。每一剂都有官印，唯独没有知情者的签名。','小果敲响洞里最后一面空铃，听见被压住的声音顺着石壁回返。蝎尾将三片解毒扇面依次钉在地上；只要声音还传得出去，这份诊断就不能替所有人作主。'],
  lore:['药方的背面写着证词删节次序：先删姓名，再删日期，最后只留一句情绪不稳。','解毒铃不是为了让人不再疼，而是让他知道自己为什么疼，仍能决定要不要开口。','大圣没带走所有毒。他把药柜锁匙留给原先被关起来的医者，说药与毒不能只由卖药的人分。'],
  tell:'跟随三片依次转向的青色解毒扇面，站在扇面中段；尾针内圈、外缘及角边均会中毒。第一片斜右上、第二片斜右下、第三片向下。',mechanic:'还言解毒：连续三片转向扇面。',bossLine:'“让你不再痛苦，难道还需要征求你的意思？”',phaseLine:'“既然治不好异议，就把听见的人也一并治了！”',omen:'看扇面中段，三次顺着解毒风换位！',weakness:'让当事人自己说，痛也不是罪！',
  reveal:'空铃响过三遍，洞中第一次传出不同的回答。蝎后遗下的药引来自解阳双生泉：从人身上夺走的那一半，被卖作另一半的解药。',clue:{name:'双生泉药引签',text:'回声穴以顺从作药，双生泉却把完整的人拆成可交易的两份。小果沿药引上游前行，要把选择还给被替人决定的人。'},reward:'毒已散，声音仍在。安静不该成为别人强加给你的康复。',regions:['改病石门','沉言药窟','空铃返廊','还言蝎坛'],siteNames:['被删节的诊籍','解毒空铃','医者药柜匙','封药遗匣','返声药庐','还言蝎坛']},
 {id:'twinspring',no:'贰拾柒',title:'双生自择',subtitle:'解阳双生泉',place:'解阳山 · 双生泉',color:'#c7dcc3',boss:'借阳真君',bossGlyph:'择',theme:'替你安排的圆满，为什么总少了你自己的选择？',
  mobNames:{imp:'双泉玉戟卒',fox:'阴阳水麟獒',snake:'分命水钵僧',zombie:'玉闸镇泉卫'},
  story:['两眼泉隔着一道玉闸，一边卖新生，一边卖解脱。借阳真君说两边都在救人，却把每个来者先分为有用的一半和该舍的一半。','泉水从不问当事人愿不愿意。家族替他选，官府替他选，连尚未存在的未来也被拿来催他签字；签得越快，账上的慈悲便越多。','大圣曾用两只空碗接泉，却没有替任何人喝下。小果将玉闸打开，让两边的水彼此看见。真君召出左右泉台和中央合流印，想证明不受安排的水只会泛滥。'],
  lore:['新生名册与解脱名册用同一把尺量人，尺上没有愿意或不愿意的刻度。','玉闸下埋着两只空碗，没有神谕，也没有代签。','两泉合流后仍有不同的温度。完整不必意味着所有人都走同一条路。'],
  tell:'先守左侧横泉椭圆，再守右侧横泉椭圆，第三拍进入中央两道泉眼的重叠交集。扁圆外缘与单泉独占区域都不算合流。',mechanic:'双泉合流：左泉、右泉、中央双泉交集。',bossLine:'“替你选好，是免你将来后悔。”',phaseLine:'“不受安排的愿望，都是祸根！”',omen:'左泉、右泉，再回中央交集，别站单泉边！',weakness:'把碗放下，让来者自己决定！',
  reveal:'玉闸碎后，第一位来者没有饮水，只在泉边坐到天明。真君的调水令指向火焰烬界关：所有未经准许的愿望，最终都要被烧成灰。',clue:{name:'烬界焚愿调令',text:'真仙篇已破。三泉与镜水凝成太玄玉髓，真仙九层圆满突破玄仙后，可循调令进入火焰烬界关。'},reward:'泉仍在，却再无人替来者举碗。选择终于可以慢一点。',regions:['代选泉门','冷暖两岸','空碗合流台','双生自择坛'],siteNames:['代签新生册','不代饮的空碗','合流温泉刻','双泉玉匣','合流药亭','双生自择坛']},
 {id:'ashfront',no:'贰拾捌',title:'火焰止界',subtitle:'火焰烬界关',place:'火焰山 · 烬界关',color:'#e9a375',boss:'焚界牛君',bossGlyph:'界',theme:'以安稳为名筑起的火墙，为什么总把最需要出路的人困在里面？',
  mobNames:{imp:'烬界火斧卒',fox:'焦角灰牛獒',snake:'封山灰扇师',zombie:'熔链镇门卫'},
  story:['调令尽头是一道烧不完的关墙。火焰山下，逃荒的人排队交愿：想去哪里，为什么要走，若一生不回谁替你作保。答不全，便被留在火里。','焚界牛君说墙外更危险，只有服从才能换来庇护。他向山外卖熄火符，却向山内收续燃税；每有一个人试图越界，火墙便被说成必须更高。','大圣留下的芭蕉旧骨插在灰里，没有风，却指着同一条通路。小果不替所有人决定去留，只要关门的人也站到火里来回答。三条冷灰走廊开始依次显露。'],
  lore:['熄火符的买家名单上，全是从未在山里住过的人。','续燃税又名守安钱。交钱的人越多，火烧得越久。','芭蕉旧骨旁写着：留在故乡可以是愿，出门求生也不该是罪。'],
  tell:'先走左侧纵向冷廊，再走右侧纵向冷廊，最后进入中央横向冷廊。冷廊为有限长方形，不能沿线跑到尽头之外。',mechanic:'烬界开路：左纵廊、右纵廊、中央横廊。',bossLine:'“墙外有多凶险，你们可曾替我想过？”',phaseLine:'“谁敢越界，就替所有留下的人受罚！”',omen:'左冷廊、右冷廊，最后横穿中央灰路！',weakness:'火墙熄了，去留由活人自己定！',
  reveal:'第一阵穿山风吹过，留在山里的人也终于能呼吸。牛君的续燃税印，竟与祭赛血珠塔的功德凭据同号：烧掉的愿望，被当作救赎的原料。',clue:{name:'祭赛续燃功德票',text:'火墙困住人，血珠塔再把困苦制成功德。小果带着初凝的金曜仙砂前往祭赛，查那颗越供越红的珠子。'},reward:'火已止，路仍留着。平安不该靠剥夺出路来证明。',regions:['续燃关口','灰骨风道','熄符旧市','止界火坛'],siteNames:['山外熄火符册','续燃守安税碑','芭蕉旧骨','熄火铁匣','灰风药棚','止界火坛']},
 {id:'bloodrelic',no:'贰拾玖',title:'祭赛还珠',subtitle:'祭赛血珠塔',place:'祭赛国 · 血珠塔',color:'#ddabaf',boss:'假愿塔僧',bossGlyph:'珠',theme:'把别人的受难供成宝物，算谁的功德？',
  mobNames:{imp:'假愿月杖卒',fox:'金珠狮纹獒',snake:'空钵供珠僧',zombie:'石塔护珠卫'},
  story:['血珠高悬塔顶，城中人每抬一次头，便被告知自己又蒙了一次恩。小果走过供养簿，发现珠光最盛的日子，恰是城外失踪人数最多的日子。','假愿塔僧说苦难需要归处，入珠者便能替后人积福。可后人的名字从来轮不到入珠者的家属，红光照亮的，总是另一本被挑选过的谱。','大圣曾把珠从神龛取下，让它在寻常人的手里冷了一夜。小果沿三处还珠印换位，塔僧驱使香火反扑：他怕的不是珠碎，而是有人发现它本来不必吃人。'],
  lore:['塔底家书只写了半页，余下的纸被裁作供养票。','城里的长明灯每月领一次油，城外的家属却被要求终身感恩。','大圣没有把珠送给另一座庙。他把看守珠子的锁匙交给了仍在寻人的家属。'],
  tell:'第一拍踏入左侧还珠小坛，第二拍转到右侧小坛，第三拍回中央向下的三角印。三角顶点与边线危险，站进印心。',mechanic:'还珠三印：左坛、右坛、中央倒三角。',bossLine:'“没有他们的苦，哪来你们看得见的光？”',phaseLine:'“供养一断，这城的福谁来担！”',omen:'左坛、右坛，再进中央倒三角印心！',weakness:'把珠还给寻找亲人的人！',
  reveal:'珠光黯下，城中没有降灾，只多了许多终于可以被念出的姓名。塔僧的空钵底藏着碧波龙宫的接货单，九颗印章都签着同一笔无主供养。',clue:{name:'九首接珠水单',text:'祭赛把受难炼成珠，碧波把珠的来路洗成无主。小果循九道水印下潜，要找到那位永远不肯亲自落款的主人。'},reward:'珠不再发红，城也没有失去天光。功德不能替受难者作证。',regions:['感恩塔门','半页家书廊','还珠三阶','空钵止供台'],siteNames:['半页供养家书','长明油账','家属守珠匙','塔影遗匣','止供药庐','空钵止供台']},
 {id:'nineledger',no:'叁拾',title:'九首归账',subtitle:'碧波九首渊',place:'碧波潭 · 九首渊',color:'#8dbfc4',boss:'九首账蛟',bossGlyph:'账',theme:'九个签名都说自己只是经手，究竟谁该为那一个人负责？',
  mobNames:{imp:'水单分叉卒',fox:'墨背蛇鳞獒',snake:'九卷漂账师',zombie:'龟账重盾卫'},
  story:['九道接货印把小果引入碧波宫。宫里的账册有九本，每本都说货从别处来，又已转往下一处；血珠绕了九圈，便被登记成没有来历的天赐。','九首账蛟每一颗头都讲得通情达理：这一头只管运输，那一头只管验印，最后一头专管劝家属不要为难办事的人。它们合起来，却能吞掉完整的一条命。','小果将九本账摊成一张方盘，不再追逐嘴上的推诿。大圣留下的逆水刻痕指向盘心：认清每一笔经手，就能让分散的责任重新连在一起。'],
  lore:['第一本账写珠是石，第四本写石是香火，第九本只剩一笔无主善款。','九枚印章的边角缺口相同，原来从未真的交过九个人的手。','逆水刻痕说：经手不是无辜的别名，替谁办事也不能免去自己看见的责任。'],
  tell:'九宫账盘先留五格青印，再换成四格青印，最后只留盘心。只进入当拍亮起的方格，灰格和格间缝隙均危险。',mechanic:'九宫归账：五格、四格、中央一格。',bossLine:'“我只是经手，你该去问下一位。”',phaseLine:'“九张嘴都说没有，你一张嘴凭什么算数！”',omen:'认准亮起的九宫方格，最后回盘心！',weakness:'九本账合起来，责任就有了名字！',
  reveal:'九首第一次说出了同一个名字：写账的人。宫门后浮出荆棘林的押运文字，原来连追问本身，也早已被写成了一种债。',clue:{name:'荆棘押问字契',text:'玄仙篇已破。九首归账凝成金曜仙砂，玄仙九层圆满突破金仙后，可进入荆棘缚字林，查是谁让文字也成了枷锁。'},reward:'经手之账已合。没有人可以只因分到一小步，就说自己从未参与。',regions:['九印水门','漂账暗渠','分责九阶','归账方盘'],siteNames:['转名九本账','同缺口印章','逆水责任刻','水单玉匣','碧波药亭','归账方盘']},
 {id:'thornscript',no:'叁拾壹',title:'荆棘解字',subtitle:'荆棘缚字林',place:'荆棘岭 · 缚字林',color:'#9ebf92',boss:'字狱木仙',bossGlyph:'字',theme:'人写下的字，怎么反过来不许人改变？',
  mobNames:{imp:'缚字钩刃卒',fox:'荆根墨纹狼',snake:'字契长笔师',zombie:'刻字木锤卫'},
  story:['字契一入荆棘林，便长出细小的刺。林中每块碑都只写半句话：有人年轻时答应的一次帮忙，被截成终生服役；有人失声时的沉默，被拓成永不反悔。','字狱木仙说落纸无改，改便是不守信。可他自己的笔下，主语能换，期限能续，唯独当事人的解释永远添不进去。太乙道莲就被压在那些删去的前后文里。','小果沿大圣折断的笔锋找回上下句，把散字连成能走人的路。木仙驱动荆棘封住直线，他便顺着折转的青色字脉前进：守信之前，总该先把话读完。'],
  lore:['碑拓只有答应二字，原纸却写着等母亲病好之后我再答应。','木仙的续期笔迹，总比当事人的签字新一年。','大圣折笔时留下的不是禁言令，而是一句请把前后文也念出来。'],
  tell:'沿第一道青色折字脉进入拐角，第二拍换到反向字脉，第三拍回中央方印。青色线有实际宽度，不能站在折线围住的空白里。',mechanic:'折字还义：两道反向字脉、中央方印。',bossLine:'“字是你自己写的，前后如何，还由得你解释？”',phaseLine:'“一字既落，千年不得改口！”',omen:'走青色折字脉，换道后回中央方印！',weakness:'把上下句还给写字的人！',
  reveal:'长满刺的半句话重新连成原意，碑林没有倒，只是第一次允许人补充。最后一页押问契盖着小雷音印：不许解释的字，被当作不许怀疑的经。',clue:{name:'小雷音释疑禁页',text:'荆棘借文字困人，小雷音借解释权让人俯首。小果携太乙道莲入倒佛堂，要问一句经文之外是否还容得下活人。'},reward:'字仍可作约，却不再替读到一半的人定罪。',regions:['半句碑口','续契荆道','折笔墨林','解字方台'],siteNames:['失去前文的碑拓','续期新笔迹','大圣折笔锋','墨契遗匣','解字药棚','解字方台']},
 {id:'falsebuddha',no:'叁拾贰',title:'雷音辨慈',subtitle:'小雷音倒佛堂',place:'小雷音 · 倒佛堂',color:'#d7c287',boss:'黄眉司契',bossGlyph:'慈',theme:'不准人走开的慈悲，究竟在度谁？',
  mobNames:{imp:'伪慈金刚卒',fox:'黄眉寺虎獒',snake:'倒钟释契僧',zombie:'覆钵重钟卫'},
  story:['倒佛堂的钟向地里响，供桌后的佛像把脸藏在暗处。黄眉司契笑着迎客，说凡是愿意进门的人，都已同意把此后的疑问交给他保管。','堂里没有牢门，只有一圈圈劝人留下的慈悲。想离开的人被说成执迷，想核对经页的人被说成心不净；越是挣扎，劝告便越像刑具。','大圣曾从覆钵下走出去，没有带走一尊像，只给后来者留下了出口的方向。小果跟随两道开口不同的青色慈环绕行，要让愿意相信与愿意离开，都不必先求赦免。'],
  lore:['入堂簿上只收录愿意入门，不记何时允许出门。','金钵内壁的戒字下，还刻着许多人试着写完的疑问。','出口的箭头旁只有一句：人能离开，留下的信才有分量。'],
  tell:'第一拍进入右侧开口慈环的中段，第二拍转到左侧慈环，最后回中央解钵圈。慈环内心、环外与被切去的开口均危险。',mechanic:'开口慈环：右环、左环、中央解钵。',bossLine:'“你若真信我，何必还要一条退路？”',phaseLine:'“出了此门，便是辜负满堂慈悲！”',omen:'只站青色慈环中段，两次绕行后回中央！',weakness:'门开着，信才不必靠囚禁维持！',
  reveal:'覆钵被抬起，堂中有人离去，也有人选择留下。黄眉的经页背后连着盘丝坊的丝线，每一句莫负慈悲，都曾被织成一个结。',clue:{name:'盘丝慈结线轴',text:'小雷音把退路说成罪，盘丝又把愧疚织成网。小果循线去找那些一生都在替别人不舍得离开的人。'},reward:'慈环已有出口。愿信者自留，愿走者不必有罪。',regions:['只入不出门','覆钵暗殿','疑问倒钟廊','解钵慈环台'],siteNames:['只有入堂的簿','钵中未完疑问','出口箭头','倒钟遗匣','释疑药亭','解钵慈环台']},
 {id:'silkpledge',no:'叁拾叁',title:'盘丝解愿',subtitle:'盘丝缠愿坊',place:'盘丝洞 · 缠愿坊',color:'#d2a4bd',boss:'七弦蛛母',bossGlyph:'结',theme:'把一生都赔进去，才算没有辜负别人吗？',
  mobNames:{imp:'红丝针刃卒',fox:'茧纹蛛足獒',snake:'缠愿纺线使',zombie:'织机缚甲卫'},
  story:['慈结线轴牵来七张织机，机上没有布，只有人答应陪伴、照料、成全时留下的声音。有人已经走到生命尽头，仍被网说成欠一次最后的回头。','七弦蛛母把每段关系都说成无价，于是没有人能算清自己究竟还欠多少。她从不强拉，只在离开的人耳边替所有人哭，一根丝便又勒紧一寸。','小果在茧里找到大圣剪开的旧结，结上留着另一端原主的名字。不是把所有牵挂烧尽，而是让两端都能亲手松开。蛛母将丝轨翻转，要拿最深的愧疚缠住握剑的手。'],
  lore:['第一张织机只记别人为你做过什么，从不记你已经做过多少。','茧中有一封迟到的回信：你可以走，不必替我的舍不得活一辈子。','大圣剪结后把剪刀放在两人之间，没有宣布谁对谁错。'],
  tell:'第一拍站进斜向三条青色丝轨之一，第二拍随翻转丝轨换位，第三拍回中央解结圈。轨道有限长，轨间空白仍是蛛网。',mechanic:'双向松结：斜丝轨、反斜丝轨、中央断结。',bossLine:'“你走得掉，可舍得让他们难过？”',phaseLine:'“每一滴眼泪，都是你还没还完的债！”',omen:'跟斜向青色丝轨，翻转后再回解结圈！',weakness:'牵挂能留下人，也该允许人松手！',
  reveal:'七张织机停了，线的两端终于能互相看见。有些结被松开，有些重新系好。坊后却运来整车无名白骨，来自狮驼万骨关的关税仓。',clue:{name:'狮驼骨税运单',text:'金仙篇已破。解开的愿结凝成太乙道莲，金仙九层圆满突破太乙金仙后，循骨税运单进入狮驼万骨关。'},reward:'丝仍可牵人，却不能再假借牵挂勒住咽喉。',regions:['慈结坊门','七机茧廊','迟信织庭','双向解结坛'],siteNames:['只记恩的织簿','迟到的回信','两人之间的剪刀','丝愿宝匣','松结药亭','双向解结坛']},
 {id:'bonecitadel',no:'叁拾肆',title:'狮驼还城',subtitle:'狮驼万骨关',place:'狮驼岭 · 万骨关',color:'#c4c5bb',boss:'吞城青狮',bossGlyph:'城',theme:'一座由人命撑起的盛世，为什么不许人问脚下是谁？',
  mobNames:{imp:'骨关长戟卒',fox:'白骨狮纹獒',snake:'空屋颅灯师',zombie:'城骨重盾卫'},
  story:['骨税运单把小果带到一座过分整洁的城。街上没有哭声，城墙却会在夜里低低作响：每一块白石，都曾是城外一个没有被记录的家。','吞城青狮自夸让荒地变成繁华，凡问白石来路的人，便被说成不肯顾全城中安稳。住在墙里的受难者，连讨回姓名都被算作扰民。','大圣曾从狮口撬下一枚牙，牙里嵌着一张寻屋图。小果循图在两组骨印之间换位，要把城墙下的人从建材重新认作邻人。狮王不怕城塌，只怕城里的人开始问。'],
  lore:['城中户籍只有入住者，地基工册却写着未经清点的整村人数。','一户空屋门牌没有字，屋里留着孩子量身高的刻痕。','大圣撬牙时说，繁华若必须让人闭嘴，便先听一听被踩在下面的人。'],
  tell:'六座骨印先亮起相隔的三座，再换为另外三座，第三拍回中央六角解城印。每座都是独立六边形，印间没有安全通道。',mechanic:'六骨还城：两组交替六角印、中央印。',bossLine:'“没这些无名骨，哪有你脚下的太平路？”',phaseLine:'“拆我的城，就是断全城人的活路！”',omen:'进亮起的六角骨印，换组后回中央！',weakness:'城可以留下，压在底下的人也要有名字！',
  reveal:'第一面骨墙被拆开，城没有倒，巷里却多了回家的路。青狮牙中的仓号连着六牙镇账殿，白骨只是进货，账上还有更大的抵押。',clue:{name:'六牙骨仓总票',text:'狮驼吞人作城，六牙将城中一切折作可抵押的数目。小果带混元道果去镇账殿，追那根把所有活路串在一起的象牙锁。'},reward:'万骨不再只是城墙。繁华的账，终于开始算上它曾踩过的人。',regions:['安稳骨门','空屋长街','寻屋牙庭','还城六骨台'],siteNames:['失去地基的户籍','空屋身高刻','大圣撬牙图','骨仓遗匣','还城药屋','还城六骨台']},
 {id:'sixivory',no:'叁拾伍',title:'六牙断押',subtitle:'六牙镇账殿',place:'六牙山 · 镇账殿',color:'#ddd4b3',boss:'六牙镇账象',bossGlyph:'押',theme:'当所有人的退路都被绑成同一笔抵押，谁还被允许先松手？',
  mobNames:{imp:'象牙押契卒',fox:'六角象纹獒',snake:'铜牙封印僧',zombie:'象盾镇仓卫'},
  story:['六根象牙贯穿镇账大殿，一根押地，一根押粮，余下四根押着姓名、明日、退路与沉默。殿中的人不是没有还清，只是每一份还清都要等别人先还。','六牙镇账象说大账不能乱，松一根牙会使千家一起受损。可最大的账页后面，早有人把最安全的那一份转走，只留下不能承担损失的人彼此作保。','小果在牙根找到大圣打断又被接回的旧痕。今次不再只砸最外面的锁，先沿六道象牙空隙换位，斩掉把无关者绑在一起的总押结。'],
  lore:['押地的账只标亩数，不标有人最后一次回家是哪一年。','最安全的一页已经被撕走，留下的每页都盖着风险共担。','大圣的旧痕被镶上金套，锁便改名为修复后的信任。'],
  tell:'六牙放出六道青色辐射空隙，连续三拍整体转过一牙。避开中央牙根及外缘，站在青色辐道中段，跟随金色印心移动。',mechanic:'六牙轮隙：三拍依次转向的六辐空隙。',bossLine:'“松你一个人的押，要害多少家一起倒？”',phaseLine:'“大账不倒，谁都不许先走！”',omen:'别进牙根，沿六辐空隙逐拍转位！',weakness:'共担不能成为永远不许脱身的锁！',
  reveal:'总押结断开，六根牙各归其位，没有一家因别人的松手而倒下。镇账象转出的安全账页，买主竟是比丘寿账城：那城专收被别人抵押掉的余生。',clue:{name:'比丘余生受让页',text:'六牙押住退路，比丘再把余生按年转卖。小果带走被藏起的安全账页，去找那些从未同意出售明日的人。'},reward:'押结已断。彼此相助，不必先交出永不退出的一生。',regions:['六押殿门','失页牙廊','共担旧阶','断押轮牙台'],siteNames:['没有归期的地账','被撕的安全页','金套接牙痕','象牙旧匣','解押药亭','断押轮牙台']},
 {id:'lifedeer',no:'叁拾陆',title:'比丘还年',subtitle:'比丘寿账城',place:'比丘国 · 寿账城',color:'#d8b7a0',boss:'寿契白鹿君',bossGlyph:'年',theme:'有人把多活几年称作天恩，却不肯说那几年从谁身上来。',
  mobNames:{imp:'朱蜡算刃卒',fox:'延寿赤角獒',snake:'命灯验年师',zombie:'巨算寿账卫'},
  story:['比丘城的老人年年庆寿，城外的孩子却年年被叫去验账。寿契白鹿君不再直接取命，只把尚未发生的岁月算成温和的捐献，连拒绝的人都被夸作尚未觉悟。','小果翻过受让页，看见一条永远向同一边倾斜的寿秤。受益者说孩子还有很长的将来，取走的人说自己不过按规办事；被取走的那几年，却没有人问他们原想怎样过。','大圣留在算盘里的金毫拨乱过一次寿数，白鹿便把算盘换成了玉秤。小果先守横向还年印，再走纵向还年印，最后站回两端同重的中央寿台。'],
  lore:['捐年单上没有签字栏，只有监护者确认与拒绝者另册。','一张画着四季的纸被夹进寿票，原主想把来年的花都看一遍。','算盘换成玉秤，旧秤砣却一枚没少；大圣的金毫仍卡在看不见的偏心里。'],
  tell:'第一拍进入横向圆角还年台的左端，第二拍进入纵向还年台上端，第三拍回中央均衡方台。台边弧角也有实际判定，站稳青色内部。',mechanic:'寿秤归衡：横向、纵向、中央圆角方台。',bossLine:'“年轻人的几年，换长者一生圆满，不也值得？”',phaseLine:'“我的寿宴，还没到散席的时候！”',omen:'横台左端、纵台上端，再回中央均衡印！',weakness:'把几年还回去，让他们自己长大！',
  reveal:'寿秤归平，城内的寿宴终于有人放下酒杯。余生受让页的最末页写着无底坠名窟：名字一旦被收走，连被拿去多少年都无从追问。',clue:{name:'无底收名封签',text:'太乙金仙篇已破。归还的岁月凝成混元道果，太乙金仙九层圆满突破大罗金仙后，可循封签下到无底坠名窟。'},reward:'寿数回到原主手里。谁的一年，都不是可以替他人说轻巧的一年。',regions:['捐年城门','拒绝另册巷','偏心玉秤庭','还年均衡台'],siteNames:['没有签字的捐年单','来年四季画','偏心秤金毫','命灯封匣','还年药屋','还年均衡台']},
 {id:'namelesspit',no:'叁拾柒',title:'无底留名',subtitle:'无底坠名窟',place:'陷空山 · 坠名窟',color:'#b9a8dc',boss:'摄名地涌姬',bossGlyph:'名',theme:'一个人被抹去姓名之后，受过的苦就可以当作没有发生吗？',
  mobNames:{imp:'坠牌链刃卒',fox:'长耳虚穴獒',snake:'摄名紫衣祭师',zombie:'黑钟镇空卫'},
  story:['封签落入无底洞，竟没有回声。洞壁挂满被拔去名字的木牌，每一块牌后都连着一段被判作查无此人的经历。小果伸手扶住一块，掌心便多了一道无人认领的旧伤。','摄名地涌姬说遗忘最是慈悲，不记得便不再受苦。可忘掉的是世人，不是受伤的人；消失的是追问的资格，不是伤口本身。鸿蒙仙髓正在那些仍不肯消散的刻痕里发光。','大圣的金毫横在洞底，像一根不许名字继续坠落的细梁。小果循三座移位的留名环前进，先让人站得住，再让他有机会把自己的事重新说完。'],
  lore:['木牌背面还有字，写着不是我不肯说，是你们说从没有我。','洞中所谓忘忧水，只擦掉旁观者手上的证词。','金毫托住最轻的木牌时，洞底第一次传回一个人的自报名姓。'],
  tell:'三座留名环依次移到左、右、中央偏上的位置。必须站在青色环带里，环心是坠名井；跟随金色印记换环，不能把环心当作安全圈。',mechanic:'移井留名：三座移位环带，避开每座井心。',bossLine:'“没有名字，就没有谁还欠你一个交代。”',phaseLine:'“把你也收进牌里，便再没人知道谁来过！”',omen:'认准环带，别进井心；左环、右环、归名环！',weakness:'名字留下，经历就不能再被说成没有！',
  reveal:'洞底的木牌不再下坠，一个个名字被托回地面。地涌姬的封签由灭法断冠城签发，收名的下一步，是让活人连抬头都失去资格。',clue:{name:'灭法收名断冠令',text:'无底窟抹去名字，断冠城抹去发问的位置。小果带鸿蒙仙髓入城，要找回那个无需头衔也能站着说话的地方。'},reward:'洞仍深，名字却不再往下落。被看见是开始，不是恩赐。',regions:['无声封签口','查无此人廊','金毫托名梁','移井留名坛'],siteNames:['木牌背面的自述','只擦证词的忘忧水','托名金毫梁','坠名石匣','留名药亭','移井留名坛']},
 {id:'crownless',no:'叁拾捌',title:'灭法还首',subtitle:'灭法断冠城',place:'灭法国 · 断冠城',color:'#c8c8bf',boss:'无首断冠王',bossGlyph:'首',theme:'除去一顶冠，不该连一个人抬头的权利也一起除去。',
  mobNames:{imp:'断冠阔刃卒',fox:'裂冕灰脊狼',snake:'无首法碑师',zombie:'冠城石壁卫'},
  story:['断冠城没有高低贵贱的称谓，却处处立着不许抬头的碑。王说除去头冠便人人平等，随后又把能解释何为平等的嘴，只留给了自己。','无首断冠王把每一个异议者都叫作旧冠余孽。城中的人若不够谦卑，便被判作仍藏野心；哪怕只想看看天，也要先证明自己没有想站到别人头上。','小果在城根找到大圣留下的一面无冕石镜。镜里没有王，只有一张张能直视彼此的脸。他踏过先宽后窄的断冠台，又沿反向台返回，要证明站直不等于称王。'],
  lore:['第一道禁令烧掉旧冠，第二道禁令禁止人议论第一道禁令由谁来解释。','低头榜上排得最高的人，连自己的脸也快记不清了。','无冕石镜从不问看镜者是谁，只要他能抬头看见自己。'],
  tell:'第一拍站入上宽下窄的青色断冠台，第二拍台形翻转，第三拍回中央菱印。斜边以内才安全，不能按长方形估算台角。',mechanic:'无冕直立：正梯台、倒梯台、中央菱印。',bossLine:'“我连冠都不要，你们为什么还不肯低头？”',phaseLine:'“谁敢站直，谁就是想做下一个我！”',omen:'先正梯台，再倒梯台，最后回中央菱印！',weakness:'站直说话，不必先向谁讨一顶冠！',
  reveal:'断冠台裂开，城中人第一次互相看见了脸。城门外仍无一滴雨，断冠王曾把全城的雨权押给凤仙，只为证明不服从者终将受天罚。',clue:{name:'凤仙押雨断罚契',text:'断冠借平等让人低头，凤仙借天罚让人认错。小果循押雨契前行，要问这场旱灾究竟等谁满意才肯结束。'},reward:'旧冠可除，人的头却不该永远低着。',regions:['低头法门','谦卑榜巷','无冕镜庭','直立断冠台'],siteNames:['禁令的解释令','低头谦卑榜','无冕石镜','断冠旧匣','直立药屋','直立断冠台']},
 {id:'droughtgate',no:'叁拾玖',title:'凤仙开雨',subtitle:'凤仙无雨门',place:'凤仙郡 · 无雨门',color:'#c8bd9d',boss:'封雨玉衡使',bossGlyph:'雨',theme:'一场惩罚若由无关的人受尽，还能叫作公道吗？',
  mobNames:{imp:'旱税缸枪卒',fox:'尘雨枯角獒',snake:'封瓮计雨师',zombie:'裂瓮重甲卫'},
  story:['凤仙的井底结着细盐，雨却被封在郡门后的大瓮里。玉衡使说此地曾有人犯错，待那人真心悔改，满郡百姓自然能等到甘霖。','犯错的人早已不在，出生于旱年的孩子却仍在替他认罪。玉衡使每日验悔，验得越久，封雨的瓮便越满；他不缺能降的水，只缺一个愿意结束惩罚的理由。','大圣曾在瓮壁划开一道细缝，留下第一滴无人代受的雨。小果沿三枚水滴印走向雨门，不再向大瓮证明谁够谦卑，只要让与罪无关的人先喝上水。'],
  lore:['验悔簿换过三代人，最初的姓名却一直不许划去。','封雨瓮的水位每年上涨，旱地的井绳却一年比一年长。','第一滴雨旁的刻痕说：受罚者若不能离开，天罚便不能只由施罚者说何时够了。'],
  tell:'第一拍进入左侧水滴印，第二拍换到右侧水滴印，第三拍回中央翻转水滴印。水滴尖端很窄，金色标记附近才有足够落脚空间。',mechanic:'开雨三滴：左滴、右滴、中央倒滴。',bossLine:'“只要还有一人不认错，这雨就不能下。”',phaseLine:'“先让他们学会敬畏，再说喝不喝得上水！”',omen:'左水滴、右水滴，再回中央倒滴印心！',weakness:'先开雨门，无关的人不必代谁受罚！',
  reveal:'雨门开时，没有天声宣布宽恕。百姓只是接起雨，像接住本该落下的东西。押雨契的主印来自玉华折兵原：天上的总账，终于露出了收兵的手。',clue:{name:'玉华收兵天印',text:'大罗金仙篇已破。首场雨凝成鸿蒙仙髓，大罗金仙九层圆满突破仙王后，可赴玉华折兵原，沿天印追到总账之前。'},reward:'雨终于落下。活着不必先证明自己配被饶恕。',regions:['盐井郡口','三代验悔巷','封雨瓮庭','开雨三滴台'],siteNames:['三代验悔簿','越满的封雨瓮','第一滴雨刻','封雨玉匣','甘霖药亭','开雨三滴台']},
 {id:'foldedarms',no:'肆拾',title:'玉华归兵',subtitle:'玉华折兵原',place:'玉华州 · 折兵原',color:'#a7bed7',boss:'九灵归账祖',bossGlyph:'兵',theme:'不准人握剑的太平，是谁一个人的太平？',
  mobNames:{imp:'折兵机关卒',fox:'九灵铁鬃獒',snake:'收锋封印师',zombie:'叠刃巨盾卫'},
  story:['收兵天印把小果引上玉华原，万千兵器像折断的树，向同一座天门弯下腰。九灵归账祖说凡兵器皆会生乱，收尽众人的锋，天下便能太平。','原上被收去的，不只是刀枪。匠人的工具、证人的笔、求生者开门的一把凿，也都被归作可能伤人的锋；唯独收兵者自己的牙，从未入过库。','大圣留在兵库的手印没有握拳，而是托着一把交还原主的锤。小果沿两道归兵折线穿行，最后站稳六角兵印，不是要人人称雄，只是不许自卫也由强者独占。'],
  lore:['兵库册把木匠凿与刑刀并列，却把九灵的牙记作天生威仪。','一柄旧锤的柄上有两层手印，后一道还留着原主的茧。','大圣没有替所有人选择兵器。他只把锁库的门从里面打开。'],
  tell:'沿第一道青色V形归兵线入印，再换到翻转折线，第三拍进入中央六角兵印。折线有宽度，V字包围的空地仍会被器影扫过。',mechanic:'归兵折线：正折、反折、中央六角兵印。',bossLine:'“世上只留一副牙，才不会再有人受伤。”',phaseLine:'“牙归天赐，剑归乱源，你岂敢并论！”',omen:'进青色折线，翻转后回中央兵印！',weakness:'太平不能只允许收兵的人握住锋！',
  reveal:'兵库门开，第一位进门的匠人只取回自己的凿。九灵的牙后藏着灵山总账副本，封面没有主人，只有每一笔都称无主的功德。',clue:{name:'灵山无主功德副册',text:'玉华收尽反抗的器，灵山却说没有谁享有收来的利。小果携归还的兵印上灵山，问一问那本始终找不到主人的总账。'},reward:'兵归各主。自卫与谋生的工具，不再由同一副牙代为保管。',regions:['万锋折门','同列兵册原','归锤旧庭','六角归兵台'],siteNames:['凿与刑刀的兵册','归主旧锤','兵库内开门刻','折锋遗匣','归兵药庐','六角归兵台']},
 {id:'ownerless',no:'肆拾壹',title:'灵山问主',subtitle:'灵山无主账殿',place:'灵山 · 无主账殿',color:'#d5cda7',boss:'无主功德相',bossGlyph:'主',theme:'人人都说自己没有取利，取走的一切又去了哪里？',
  mobNames:{imp:'无主玉戟卒',fox:'空册云麟獒',snake:'功德三印师',zombie:'浮金账盾卫'},
  story:['灵山总账殿比想象中安静，金座上空无一人。每一笔受难都被写成功德，每一笔受益都被记作众生共有；唯独真正的众生，进不了查阅这本账的门。','无主功德相没有脸，谁开口，它便用谁相信的声音回答：这是秩序，这是大局，这是大家都同意的事。小果从未见过如此完满的托词，连追问该问谁都成了问题。','四十一道线索在殿中接成一张有去有回的路。大圣没有坐上金座，他把自己的那一页也摊在桌上。小果依次站入三道互证功德印的交心，要让受益、决定与责任重新指向同一个地方。'],
  lore:['总账的查阅规程写着公开，门禁名册却从来不包括被记账的人。','金座上的尘一层未动，座后的分配册却每天添新页。','大圣自己的旧账也有被划改的地方。他留下笔，不许后来者只查别人。'],
  tell:'三道圆印必须同时覆盖身体才算互证：先去左侧三印交心，再去右侧交心，最后回中央交心。单圆内、双圆交集及金座周围都不安全。',mechanic:'三印互证：左、右、中央三圆共同交集。',bossLine:'“这里没有主人，你要追究谁？”',phaseLine:'“每个人都得过一点，你还分得清谁欠谁吗！”',omen:'只进三圆共同交心，左、右、中央依次走！',weakness:'没有主人的账，也必须有人为决定负责！',
  reveal:'三印相合，无主相的脸终于显出每一位曾经代签者的影子。总账最后一页并不在灵山，而被悬到天外：执契天衡在那里，专替一切永不改口的决定作保。',clue:{name:'天外归名终契',text:'四十一道线索已合。账殿不再能以无主搪塞，小果带着大圣也未能免去的那一页旧账，前往天外归名石庭，结束不容活人改写的终契。'},reward:'账殿已有回应。众人共有，不能再成为无人负责的别名。',regions:['公开闭门阶','无人金座廊','自查旧账庭','三印问主台'],siteNames:['公开查阅门禁册','金座后分配页','大圣自查旧页','无主金匣','互证药亭','三印问主台']},
 {id:'returnstone',no:'肆拾贰',title:'天外归名',subtitle:'天外归名石庭',place:'天外 · 归名石庭',color:'#d5dfeb',boss:'执契天衡',bossGlyph:'归',theme:'走到最后，能不能把连大圣也绑住的那一本账，交还给活人改写？',
  mobNames:{imp:'终契星刃卒',fox:'归名星鬃獒',snake:'天衡量契师',zombie:'裂庭巨石卫'},
  story:['天外没有更高的殿，只有一座横在星河上的石庭。四十一道线索同时发亮，执契天衡立在裂缝前，说每一桩买卖、每一道命令都有签字，若今日容你推翻，明日便再无人肯信任何一句话。','大圣从终契背后走出，身上的金箍不在头顶，而化成一行行替众生担过的旧名。他不是从未犯错的救主，也没有替后来者写好答案；他只是把那根始终没有交出去的笔，递到了孙小果手边。','小果没有在终契上写下新的主人。他先断去把人逼到无路可退的条款，再让决定的人亲自回应后果。天衡的三重契相依次显露：照面、断衡、归名。最后这一剑，要给今后仍会争执的活人，留下一条重新商量的路。'],
  lore:['终契保存着所有答应，却没有一栏记录当时是否还有别的活路。','大圣旧名里有救过的人，也有没能救下的人；没有哪一行允许他替别人永远作主。','空白新册的第一页没有天条，只有一列仍可补写的名字。'],
  tell:'天衡三相会改变仪式：照面相走左右弯月与镜心，断衡相走正反六辐与中央印，归名相走左右三印交心再回中央。每轮只显示当前一拍青色区域，连续三拍完成获3倍伤害；本体始终可攻击。',mechanic:'终契三相：照面、断衡、归名，随生命阶段改变三拍仪式。',bossLine:'“若一切都能重议，谁来替永远二字担保？”',phaseLine:'“你要毁的，究竟是旧契，还是天地信得过的一切！”',omen:'看当前契相与青印，三拍走完再出剑！',weakness:'约定可以守，也必须容活人一起重议！',
  reveal:'终契裂开，没有新的天衡坐上旧位。金毫化作一条通往人间的细路，大圣把自己的名字写回人群，也把笔留在新册旁。天亮后，仍有人争执、有人失约；但再没有谁能拿一本永不改写的账，替所有人决定一生。',clue:{name:'众生可改的新册',text:'四十二难已破，寻圣主线完结。你寻到的不是替众生永久作主的圣，而是愿意把姓名、责任与改写之权一并交还的同行者。此后可阅终章、重游各关或挑战已解锁域外大妖。'},reward:'名字归人，笔仍留着。路到这里结束，活人的明日从这里继续。',regions:['终契星门','无路可退廊','大圣旧名庭','众生归名台'],siteNames:['没有退路的终契','大圣也在的旧名','可补写的空白册','终契石匣','归名药亭','众生归名台']}
];

